// The home continue rail (browse-scale D5): ONE server-composed round-trip
// the SPA's home surface renders from — the caller's progress rows, scored
// and ordered through the SAME recs composition the /progress listing
// serves (score-then-window: the full set is read, scored, ordered, THEN cut
// to the ≤50 bound), each served row restyled into a ContinueRow: the series
// and current item through namerFor, the next-episode pick with the watch
// page's tuple rule, the honest duration floor, and query-time artwork over
// the bounded set. The route takes no parameters by design (D5's declined
// alternatives): the rail has no paging or shape-branching seam in v1.
//
// Viewer posture (6.2, the recommendation-sorting visibility mandate carried
// onto this route): every read below — the ledger read inside recsFactsFor,
// scoreProgress's composition, the per-row item reads, the episode reads —
// is the CALLING VIEWER's, so a library outside the visible set contributes
// no rows at all (no ids, no names, no counts), and namerFor receives
// v.ChainMutes so names and artwork mute exactly like every other
// browse-group route. The watched-ledger rows are NOT withdrawn here (the
// /progress default's withdrawal does not carry over): a completed episode
// keeps its positive progress row, and that row is the next-anchor its
// series' pick derives from — the fused next affordance is exactly what the
// SPA's separate Next-up section consumed the served rows for. The wire
// carries no watched flag; a row renders as a resume point or a next anchor,
// never both lies at once.

package api

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"net/http"
	"strconv"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/naming"
	"github.com/mellifera/mellifera/internal/store"
)

// homeBound is D5's ≤50: the hard server-side cap on the rail's rows. The
// cut lands AFTER the score order (score-then-window), so a high scorer can
// never fall behind the window the way an SQL LIMIT would cut it.
const homeBound = 50

// homeResponse is the wire shape for GET /api/v1/home (browse-scale D7).
type homeResponse struct {
	Continue []continueRow `json:"continue"`
}

// continueRow is ONE continue rail row: the series the current item anchors
// to (its served id, display name, artwork) beside the row's resume facts.
// A row whose item carries no series anchor — a film or tv item — serves the
// series fields as "" (honest absence, never a fabricated owner; the SPA's
// fallback chain reads the empty strings as absent) and never carries next.
type continueRow struct {
	SeriesID      string `json:"series_id"`
	SeriesDisplay string `json:"series_display_name"`
	LibraryID     int64  `json:"library_id"`
	LibraryName   string `json:"library_name"`
	// Artwork is the query-time composed poster URL (artwork): the owning
	// series' for serial rows, the item's own (with the owning-series
	// fallback) for films — resolved over the bounded row set per request,
	// never from a cache of display bytes. Absent (omitempty) when nothing
	// composes — honest absence, never a placeholder.
	Artwork string          `json:"artwork,omitempty"`
	Current continueCurrent `json:"current"`
	// Next is the next-episode offer — omitted (omitempty) when none: films
	// never carry it (an episode concept), and neither does a series whose
	// highest-started episode is also its last, or whose remaining episodes
	// carry no parseable facts.
	Next *continueNext `json:"next,omitempty"`
}

// continueCurrent is the row's resume point: the item to deep-link into, its
// served display name, the parsed episode identity when the document carries
// it, the episode's own convention title when the metadata projection
// resolves one, the stored position, and the item's ffprobe duration when
// the document stores it (omitted otherwise — the honest absence a client
// renders as a bar-less row).
type continueCurrent struct {
	ItemID          string `json:"item_id"`
	Display         string `json:"display_name"`
	Season          *int64 `json:"season,omitempty"`
	Episode         *int64 `json:"episode,omitempty"`
	EpisodeTitle    string `json:"episode_title,omitempty"`
	PositionSeconds int64  `json:"position_seconds"`
	DurationSeconds *int64 `json:"duration_seconds,omitempty"`
}

// continueNext is the row's Play-able suggestion: the episode item to
// deep-link into and the SxxEyy label composed from its raw episode facts
// (facts stay raw on the wire; only the pick moved server-side).
type continueNext struct {
	ItemID string `json:"item_id"`
	Label  string `json:"label"`
}

// home: the caller's full positive-progress set → recsFactsFor's batched
// reads → scoreProgress's per-library scoring → orderByScoreRecency → the
// homeBound cut → ContinueRow composition over the bounded set.
//
// @Summary      Continue rail (home)
// @Tags         home
// @ID           get-home
// @Router       /home [get]
// @Success      200 {object} homeResponse
// @Failure      500 {object} errorBody
func (a *app) home(w http.ResponseWriter, r *http.Request) {
	// The caller's ledger scope (6.2): the scored composition below — the
	// batched reads, the score, the row reads — is the requesting viewer's
	// own slot over its visible libraries.
	v, ctx := a.viewerFor(r)
	facts, err := a.recsFactsFor(ctx, v)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	// The scored default, exactly as the /progress listing composes it: the
	// full positive set is scored (InProgress holds for every row — a resume
	// surface), ordered score-desc/recency, THEN cut to the bound.
	scores, err := a.scoreProgress(ctx, v, facts.rows, facts)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	entries := make([]progressScored, len(facts.rows))
	for i, row := range facts.rows {
		entries[i] = progressScored{row: row, score: scores[i]}
	}
	orderByScoreRecency(entries)
	if len(entries) > homeBound {
		entries = entries[:homeBound]
	}
	rows, err := a.homeRows(ctx, v, entries)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	writeJSON(w, http.StatusOK, homeResponse{Continue: rows})
}

// homeLoad is one bounded row's composition input: the scored pair, the
// item row it point-reads into, and the parsed episode identity (the
// film/tv shape is hasFacts=false — no parsed anchor, no parseable pair).
type homeLoad struct {
	scored   progressScored
	item     store.Item
	path     string
	season   int64
	episode  int64
	hasFacts bool
}

// homeRows composes the bounded set into ContinueRows IN SERVED ORDER. The
// rows span libraries, and every composition leg is per-library (namerFor's
// whole-library series read, artworkFor's batched overrides read), so the
// work groups by library — one namer, one library row, two batched artwork
// passes, and one episode read per DISTINCT series — and the composed rows
// re-assemble in the served order afterwards. A row whose item vanished
// between the ledger read and the point read (the store JOINs ListProgress
// to items, so this is a between-reads race only) is skipped — honest
// absence, never a half-composed row.
func (a *app) homeRows(ctx context.Context, v access.Viewer, entries []progressScored) ([]continueRow, error) {
	loads := make([]*homeLoad, 0, len(entries))
	byLib := make(map[int64][]*homeLoad, len(entries))
	for _, e := range entries {
		it, err := a.deps.Store.GetItem(ctx, e.row.ItemID, v)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				continue // gone between reads — the row serves nothing
			}
			return nil, err
		}
		path, s, ep, ok := naming.EpisodeFacts(naming.DocMap(it.Document))
		l := &homeLoad{scored: e, item: it, path: path, season: s, episode: ep, hasFacts: ok}
		loads = append(loads, l)
		byLib[it.LibraryID] = append(byLib[it.LibraryID], l)
	}
	composed := make(map[string]continueRow, len(loads))
	for libID, libLoads := range byLib {
		rows, err := a.homeLibRows(ctx, v, libID, libLoads)
		if err != nil {
			return nil, err
		}
		for id, row := range rows {
			composed[id] = row
		}
	}
	out := make([]continueRow, 0, len(loads))
	for _, l := range loads {
		if row, ok := composed[l.item.ID]; ok {
			out = append(out, row)
		}
	}
	return out, nil
}

// homeSeries is one touched series' per-library composition state: the
// resolved row (served=false when the anchor matches nothing or a
// tombstone — the SPA's matchSeries skips deleted rows), its stored title
// override, the HIGHEST started (season, episode) across this response's
// own rows for the series (the exact input the SPA's startedSeries derived
// from the served progress rows), and the series' episode rows (read once
// per series, lazily — the next pick's only extra read).
type homeSeries struct {
	sr       store.Series
	served   bool
	override string
	startS   int64
	startE   int64
	eps      []store.Item
	epsRead  bool
}

// homeLibRows composes one library's bounded rows. Every store read here is
// either batched per library (the artwork passes) or once per distinct
// series (the override, the episode read) — never per row beyond the
// per-row override point reads the DTO seam's documented MVP posture
// already prices (itemDTOs; display-naming D-9).
func (a *app) homeLibRows(ctx context.Context, v access.Viewer, libID int64, loads []*homeLoad) (map[string]continueRow, error) {
	// One namer per distinct library per request — the scoreProgress
	// convention — fed the CALLING VIEWER's ChainMutes (l6-accounts 10.4):
	// names mute exactly like every other browse route.
	n, err := a.namerFor(ctx, libID, v.ChainMutes)
	if err != nil {
		return nil, err
	}
	libName := ""
	lib, err := a.deps.Store.GetLibrary(ctx, libID, access.System())
	switch {
	case err == nil:
		libName = lib.DisplayName
	case errors.Is(err, sql.ErrNoRows):
		// The library row vanished: the namer above already floored empty,
		// and the display name floors with it (honest absence — the same
		// missing-library floor every namerFor call site shares).
	default:
		return nil, err
	}
	// Series resolution + the per-series started-max, one walk over the
	// library's rows.
	series := make(map[string]*homeSeries, len(loads))
	for _, l := range loads {
		if !l.hasFacts {
			continue
		}
		sc, ok := series[l.path]
		if !ok {
			sc = &homeSeries{}
			if cand, has := n.SeriesByPath[l.path]; has && cand.Status != "deleted" {
				ov, err := a.storedTitle(ctx, cand.ID)
				if err != nil {
					return nil, err
				}
				sc.sr, sc.served, sc.override = cand, true, ov
			}
			series[l.path] = sc
		}
		if l.season > sc.startS || (l.season == sc.startS && l.episode > sc.startE) {
			sc.startS, sc.startE = l.season, l.episode
		}
	}
	// Query-time artwork over the bounded set (artwork D3): serial rows ride
	// their OWNING SERIES' composition, films ride the item leg with its
	// lazy series fallback — both the batched artworkFor passes, under the
	// caller's mutes.
	var serialArt, filmArt []artRow
	seenArt := make(map[string]bool, len(loads))
	for _, l := range loads {
		if !l.hasFacts {
			if !seenArt[l.item.ID] {
				seenArt[l.item.ID] = true
				filmArt = append(filmArt, artRow{id: l.item.ID, path: l.item.RelativePath, doc: l.item.Document})
			}
			continue
		}
		if sc := series[l.path]; sc.served && !seenArt[sc.sr.ID] {
			seenArt[sc.sr.ID] = true
			serialArt = append(serialArt, artRow{id: sc.sr.ID, doc: sc.sr.Document})
		}
	}
	seriesArt := map[string]string{}
	if len(serialArt) > 0 {
		if seriesArt, err = a.artworkFor(ctx, artKindSeries, serialArt, n, nil, v.ChainMutes); err != nil {
			return nil, err
		}
	}
	filmArtMap := map[string]string{}
	if len(filmArt) > 0 {
		// The item leg's lazy series-fallback read (one per library, made by
		// artworkFor only when some film resolved absent) — the same
		// closure shape itemDTOs builds.
		seriesOf := func(ctx context.Context) ([]store.Series, error) {
			return a.deps.Store.QuerySeries(ctx, libID, "", access.System())
		}
		if filmArtMap, err = a.artworkFor(ctx, artKindItem, filmArt, n, seriesOf, v.ChainMutes); err != nil {
			return nil, err
		}
	}
	// Row composition.
	out := make(map[string]continueRow, len(loads))
	for _, l := range loads {
		row := continueRow{
			LibraryID:   libID,
			LibraryName: libName,
			Current: continueCurrent{
				ItemID:          l.item.ID,
				PositionSeconds: l.scored.row.PositionSeconds,
			},
		}
		var sc *homeSeries
		if l.hasFacts {
			// The raw episode identity on the wire (facts stay raw; only
			// naming and picking are server-composed) — served whenever the
			// document parses, independent of series resolution.
			s, e := l.season, l.episode
			row.Current.Season = &s
			row.Current.Episode = &e
			sc = series[l.path]
		}
		if sc != nil && sc.served {
			row.SeriesID = sc.sr.ID
			row.SeriesDisplay = n.SeriesName(sc.sr, sc.override)
			row.Artwork = seriesArt[sc.sr.ID]
		} else if !l.hasFacts {
			row.Artwork = filmArtMap[l.item.ID]
		}
		// The current item's served display name — the SAME seam the item
		// listing stamps (toItemDTO): the row's own override over the
		// series-override-carrying namer's ItemName chain. The series
		// override is already point-read above, so it is set directly (the
		// withSeriesOverride point read would resolve the identical row).
		ov, err := a.storedTitle(ctx, l.item.ID)
		if err != nil {
			return nil, err
		}
		nn := n
		if sc != nil && sc.served {
			nn.SeriesOverride = sc.override
		}
		row.Current.Display = nn.ItemName(l.item, ov)
		// The episode's own convention title — the SAME projection the
		// About panel renders (metadataFor's episode group; the winner
		// namespace's title member verbatim). Any non-string floors to
		// absent — never a fabricated "".
		if l.hasFacts {
			if md := n.MetadataFor(l.item.Document); md != nil {
				if ep, ok := md["episode"].(map[string]any); ok {
					if t, ok := ep["title"].(string); ok {
						row.Current.EpisodeTitle = t
					}
				}
			}
		}
		// The honest duration: the verbatim ffprobe fact, or nothing.
		if d, ok := homeDurationSeconds(naming.DocMap(l.item.Document)); ok {
			row.Current.DurationSeconds = &d
		}
		// The next pick (never for films, never without a served series):
		// the series' episode rows read once per series, the pick strictly
		// after the highest STARTED episode of the response's rows.
		if sc != nil && sc.served {
			if !sc.epsRead {
				sc.epsRead = true
				eps, err := a.deps.Store.QueryItemsBySeries(ctx, sc.sr, seriesBacking(sc.sr.Document), v)
				if err != nil {
					return nil, err
				}
				sc.eps = eps
			}
			if id, label, ok := homeNextPick(sc.eps, sc.startS, sc.startE); ok {
				row.Next = &continueNext{ItemID: id, Label: label}
			}
		}
		out[l.item.ID] = row
	}
	return out, nil
}

// homeNextPick is the next-episode pick, tuple parity with the watch page's
// client derivation pinned (nextup.ts nextEpisodeAfter — the exact vectors
// the SPA test pins live re-pinned here): the LOWEST (season, episode) pair
// STRICTLY AFTER the started pair, taken from the series' episode rows.
// Candidates without parseable episode facts are skipped, never fatal; the
// started pair itself (equal facts) never wins; nothing strictly after —
// none at all, or none parseable — is ok=false, the caller omits next.
func homeNextPick(eps []store.Item, startedSeason, startedEpisode int64) (itemID, label string, ok bool) {
	found := false
	var bestS, bestE int64
	for _, ep := range eps {
		_, s, e, fok := naming.EpisodeFacts(naming.DocMap(ep.Document))
		if !fok {
			continue
		}
		if !(s > startedSeason || (s == startedSeason && e > startedEpisode)) {
			continue
		}
		if !found || s < bestS || (s == bestS && e < bestE) {
			found, bestS, bestE, itemID = true, s, e, ep.ID
		}
	}
	if !found {
		return "", "", false
	}
	return itemID, fmt.Sprintf("S%02dE%02d", bestS, bestE), true
}

// homeDurationSeconds reads the item's total whole-second duration from the
// verbatim ffprobe blob — parity with the SPA's durationSeconds (Home.tsx):
// ffprobe writes format.duration as a decimal-seconds string, and the doc
// decode keeps JSON numbers as json.Number, so both shapes parse. Anything
// missing, mistyped, unparseable, non-finite, or non-positive floors to
// ok=false — the caller omits the field rather than guessing (the bar-less
// row the client renders).
func homeDurationSeconds(doc map[string]any) (int64, bool) {
	if doc == nil {
		return 0, false
	}
	ff, _ := doc["ffprobe"].(map[string]any)
	if ff == nil {
		return 0, false
	}
	format, _ := ff["format"].(map[string]any)
	if format == nil {
		return 0, false
	}
	var raw string
	switch v := format["duration"].(type) {
	case string:
		raw = v
	case json.Number:
		raw = v.String()
	default:
		return 0, false
	}
	f, err := strconv.ParseFloat(raw, 64)
	if err != nil || math.IsNaN(f) || math.IsInf(f, 0) || f <= 0 {
		return 0, false
	}
	return int64(math.Round(f)), true
}
